$rows = Get-Content "$S\repos.json" -Raw | ConvertFrom-Json
$req = @('README.md','pyproject.toml','.mcp.json','.gitignore','mcp/server.py','mcp/test_server.py','.claude/skills/limpiando-enaho/SKILL.md','.claude/skills/graficando-enaho/SKILL.md','.claude/skills/mapeando-enaho/SKILL.md','salidas/validacion.txt','salidas/indicadores.csv','evaluacion/preguntas.csv','evaluacion/resultados.csv','evaluacion/comparacion.md','informes/informe_final.md')
$res=@()
foreach($r in $rows){
  $url="https://api.github.com/repos/$($r.owner)/$($r.repo)/git/trees/$($r.branch)?recursive=1"
  try{ $t=Invoke-RestMethod $url -ErrorAction Stop }catch{ $res+=[pscustomobject]@{user=$r.user;err=$_.Exception.Message};continue}
  $paths = $t.tree | ? {$_.type -eq 'blob'} | % {$_.path}
  $b = $r.base; $pre = if($b){"$b/"}else{''}
  $rel = $paths | ? {$_.StartsWith($pre)} | % {$_.Substring($pre.Length)}
  $miss = $req | ? { $rel -notcontains $_ }
  $o=[ordered]@{user=$r.user; trunc=$t.truncated; files=$rel.Count
    missing=($miss -join ', ')
    figuras=($rel | ? {$_ -like 'figuras/*'}).Count
    mapas=($rel | ? {$_ -like 'mapas/*'}).Count
    evid=($rel | ? {$_ -like 'evidencias_ia/*'}).Count
    evid_sub=((($rel | ? {$_ -like 'evidencias_ia/*/*'}) | % {($_ -split '/')[1]} | sort -Unique) -join ',')
    tests=($rel | ? {$_ -match 'test.*\.py$'}) -join ';'
    bigdata=(($rel | ? {$_ -match '\.(dta|zip|sav|parquet|geojson)$'}) -join ';')
    secrets=(($rel | ? {$_ -match '(^|/)\.env$|credential|secret|token'}) -join ';')}
  $res+=[pscustomobject]$o
}
$res | ConvertTo-Json -Depth 4 | Set-Content "$S\audit.json"
$res | % { "{0} | files={1} fig={2} map={3} evid={4} [{5}]`n   MISSING: {6}`n   tests: {7}`n   data: {8} secrets: {9}" -f $_.user,$_.files,$_.figuras,$_.mapas,$_.evid,$_.evid_sub,$_.missing,$_.tests,$_.bigdata,$_.secrets; if($_.err){"ERR "+$_.err} }

